import{_ as a,o as d,c as e,a0 as i}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"Web 界面","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/webui.md","filePath":"zh-CN/guide/webui.md"}'),l={name:"zh-CN/guide/webui.md"};function r(o,t,h,s,n,c){return d(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="web-界面" tabindex="-1">Web 界面 <a class="header-anchor" href="#web-界面" aria-label="Permalink to &quot;Web 界面&quot;">​</a></h1><p>AirlineSim Autobuy 内嵌了一个基于 Vue 3 的 Web 管理界面，提供完整的图形化管理功能。默认地址为 <code>http://localhost:9090</code>。</p><h2 id="仪表盘" tabindex="-1">仪表盘 <a class="header-anchor" href="#仪表盘" aria-label="Permalink to &quot;仪表盘&quot;">​</a></h2><p>仪表盘是 Web 界面的首页，展示引擎运行状态和统计信息。</p><h3 id="引擎控制" tabindex="-1">引擎控制 <a class="header-anchor" href="#引擎控制" aria-label="Permalink to &quot;引擎控制&quot;">​</a></h3><p>页面顶部提供引擎的启动/停止控制按钮：</p><ul><li><strong>启动引擎</strong> — 开始监控所有配置的服务器</li><li><strong>停止引擎</strong> — 停止所有监控活动</li></ul><p>引擎状态指示器显示当前是否在运行中。</p><h3 id="统计概览" tabindex="-1">统计概览 <a class="header-anchor" href="#统计概览" aria-label="Permalink to &quot;统计概览&quot;">​</a></h3><p>仪表盘展示以下全局统计数据：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>扫描次数</td><td>自启动以来的市场扫描总次数</td></tr><tr><td>发现飞机</td><td>匹配到规则的飞机总数</td></tr><tr><td>购买成功</td><td>成功购买的飞机总数</td></tr><tr><td>购买失败</td><td>购买失败的次数</td></tr><tr><td>最后扫描</td><td>最近一次扫描的时间</td></tr><tr><td>最后错误</td><td>最近一次错误的详细信息</td></tr></tbody></table><h3 id="服务器状态" tabindex="-1">服务器状态 <a class="header-anchor" href="#服务器状态" aria-label="Permalink to &quot;服务器状态&quot;">​</a></h3><p>每个配置的服务器都有独立的状态卡片，显示：</p><ul><li>服务器主机名</li><li>该服务器的扫描次数</li><li>发现的飞机数量</li><li>购买成功/失败计数</li><li>最后扫描时间</li><li>最后错误信息</li></ul><h2 id="规则页面" tabindex="-1">规则页面 <a class="header-anchor" href="#规则页面" aria-label="Permalink to &quot;规则页面&quot;">​</a></h2><p>规则页面提供完整的规则管理功能，支持对规则的增删改查。</p><h3 id="规则列表" tabindex="-1">规则列表 <a class="header-anchor" href="#规则列表" aria-label="Permalink to &quot;规则列表&quot;">​</a></h3><p>以表格形式展示所有配置的规则，每行显示：</p><ul><li>启用/禁用开关</li><li>规则名称</li><li>优先级</li><li>匹配条件摘要</li><li>操作设置摘要</li><li>操作按钮（编辑、删除、切换）</li></ul><h3 id="创建规则" tabindex="-1">创建规则 <a class="header-anchor" href="#创建规则" aria-label="Permalink to &quot;创建规则&quot;">​</a></h3><p>点击&quot;添加规则&quot;按钮打开创建表单，包含以下字段：</p><p><strong>基本信息</strong></p><ul><li>规则名称</li><li>启用/禁用</li><li>优先级（1-100）</li></ul><p><strong>匹配条件</strong></p><ul><li>飞机系列（下拉选择，数据来自游戏市场）</li><li>飞机型号（下拉选择）</li><li>手动输入型号列表</li><li>最低价格</li><li>最高价格</li><li>最大机龄（年）</li><li>最大飞行循环数</li><li>最低机身状态（%）</li><li>交易类型（拍卖/立即购买/全选）</li><li>融资方式（现金/贷款/租赁）</li><li>排序方式</li></ul><p><strong>操作设置</strong></p><ul><li>自动购买开关</li><li>最大加价幅度（AS$）</li></ul><h3 id="编辑规则" tabindex="-1">编辑规则 <a class="header-anchor" href="#编辑规则" aria-label="Permalink to &quot;编辑规则&quot;">​</a></h3><p>点击规则行中的&quot;编辑&quot;按钮，打开与创建规则相同的表单，预填当前规则的配置。</p><h3 id="启用-禁用规则" tabindex="-1">启用/禁用规则 <a class="header-anchor" href="#启用-禁用规则" aria-label="Permalink to &quot;启用/禁用规则&quot;">​</a></h3><p>通过规则列表中的开关按钮，或在详情页使用&quot;切换&quot;操作，可以快速启用或禁用规则。</p><h3 id="删除规则" tabindex="-1">删除规则 <a class="header-anchor" href="#删除规则" aria-label="Permalink to &quot;删除规则&quot;">​</a></h3><p>点击&quot;删除&quot;按钮并确认后，规则将从配置中移除。</p><h3 id="规则排序" tabindex="-1">规则排序 <a class="header-anchor" href="#规则排序" aria-label="Permalink to &quot;规则排序&quot;">​</a></h3><p>规则的显示顺序（在 Web 界面中）可以通过拖拽或重新排序操作进行调整。排序使用 <code>PUT /api/rules/reorder</code> 接口实现。</p><h2 id="设置页面" tabindex="-1">设置页面 <a class="header-anchor" href="#设置页面" aria-label="Permalink to &quot;设置页面&quot;">​</a></h2><p>设置页面允许通过 Web 界面修改全局配置（不包括规则）。</p><h3 id="服务器配置" tabindex="-1">服务器配置 <a class="header-anchor" href="#服务器配置" aria-label="Permalink to &quot;服务器配置&quot;">​</a></h3><p>添加、编辑或删除游戏服务器。每个服务器需要配置：</p><ul><li>主机标识名</li><li>基础 URL</li></ul><h3 id="认证配置" tabindex="-1">认证配置 <a class="header-anchor" href="#认证配置" aria-label="Permalink to &quot;认证配置&quot;">​</a></h3><p>管理认证账户，支持多账户配置：</p><ul><li>用户名</li><li>密码（显示为掩码）</li><li>会话文件路径</li></ul><h3 id="监控设置" tabindex="-1">监控设置 <a class="header-anchor" href="#监控设置" aria-label="Permalink to &quot;监控设置&quot;">​</a></h3><p>调整市场监控参数：</p><ul><li>轮询间隔（秒）</li><li>随机延迟（秒）</li><li>请求超时（秒）</li><li>最低余额保护（AS$）</li></ul><h3 id="通知设置" tabindex="-1">通知设置 <a class="header-anchor" href="#通知设置" aria-label="Permalink to &quot;通知设置&quot;">​</a></h3><p>配置通知渠道：</p><ul><li>控制台输出开关</li><li>Discord Webhook URL</li></ul><h3 id="webui-设置" tabindex="-1">WebUI 设置 <a class="header-anchor" href="#webui-设置" aria-label="Permalink to &quot;WebUI 设置&quot;">​</a></h3><p>调整 Web 界面本身的参数：</p><ul><li>启用/禁用</li><li>监听地址</li><li>端口</li></ul><h3 id="保存设置" tabindex="-1">保存设置 <a class="header-anchor" href="#保存设置" aria-label="Permalink to &quot;保存设置&quot;">​</a></h3><p>修改后点击&quot;保存&quot;按钮，配置会通过 API 更新并持久化到 YAML 文件中。</p><h2 id="日志页面" tabindex="-1">日志页面 <a class="header-anchor" href="#日志页面" aria-label="Permalink to &quot;日志页面&quot;">​</a></h2><p>日志页面提供实时的事件查看功能。</p><h3 id="事件流" tabindex="-1">事件流 <a class="header-anchor" href="#事件流" aria-label="Permalink to &quot;事件流&quot;">​</a></h3><p>按时间倒序显示所有事件，每条事件包含：</p><ul><li>时间戳</li><li>事件类型（图标区分）</li><li>事件消息</li><li>详细描述（可展开）</li></ul><h3 id="事件类型图标" tabindex="-1">事件类型图标 <a class="header-anchor" href="#事件类型图标" aria-label="Permalink to &quot;事件类型图标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件类型</th><th>图标</th><th>说明</th></tr></thead><tbody><tr><td>发现飞机</td><td>🔍</td><td>检测到匹配规则的飞机</td></tr><tr><td>购买成功</td><td>🛒</td><td>成功完成购买</td></tr><tr><td>购买失败</td><td>❌</td><td>购买操作失败</td></tr><tr><td>出价成功</td><td>💰</td><td>成功提交竞拍出价</td></tr><tr><td>错误</td><td>⚠️</td><td>系统运行错误</td></tr><tr><td>信息</td><td>ℹ️</td><td>一般信息通知</td></tr></tbody></table><h3 id="自动刷新" tabindex="-1">自动刷新 <a class="header-anchor" href="#自动刷新" aria-label="Permalink to &quot;自动刷新&quot;">​</a></h3><p>日志页面会定期自动刷新，确保显示最新的事件。</p><h2 id="导航" tabindex="-1">导航 <a class="header-anchor" href="#导航" aria-label="Permalink to &quot;导航&quot;">​</a></h2><p>Web 界面顶部导航栏包含：</p><ul><li><strong>仪表盘</strong> — 引擎状态和统计</li><li><strong>规则</strong> — 规则管理</li><li><strong>设置</strong> — 全局配置</li><li><strong>日志</strong> — 实时事件日志</li></ul><h2 id="api-端点" tabindex="-1">API 端点 <a class="header-anchor" href="#api-端点" aria-label="Permalink to &quot;API 端点&quot;">​</a></h2><p>Web 界面通过 REST API 与后端通信。以下是前端使用的 API 端点列表：</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/status</code></td><td>获取引擎运行状态</td></tr><tr><td><code>POST</code></td><td><code>/api/control/start</code></td><td>启动监控引擎</td></tr><tr><td><code>POST</code></td><td><code>/api/control/stop</code></td><td>停止监控引擎</td></tr><tr><td><code>POST</code></td><td><code>/api/reload</code></td><td>重新加载规则</td></tr><tr><td><code>GET</code></td><td><code>/api/config</code></td><td>获取完整配置</td></tr><tr><td><code>PUT</code></td><td><code>/api/config</code></td><td>更新全局配置</td></tr><tr><td><code>GET</code></td><td><code>/api/rules</code></td><td>获取规则列表</td></tr><tr><td><code>POST</code></td><td><code>/api/rules</code></td><td>创建新规则</td></tr><tr><td><code>GET</code></td><td><code>/api/rules/{id}</code></td><td>获取单条规则</td></tr><tr><td><code>PUT</code></td><td><code>/api/rules/{id}</code></td><td>更新单条规则</td></tr><tr><td><code>DELETE</code></td><td><code>/api/rules/{id}</code></td><td>删除规则</td></tr><tr><td><code>PATCH</code></td><td><code>/api/rules/{id}/toggle</code></td><td>切换规则的启用状态</td></tr><tr><td><code>PUT</code></td><td><code>/api/rules/reorder</code></td><td>重新排序规则</td></tr><tr><td><code>GET</code></td><td><code>/api/aircraft-data</code></td><td>获取飞机市场参考数据</td></tr></tbody></table><p>完整的 API 文档请参阅 <a href="./../reference/api.html">API 参考</a>。</p><h2 id="开发模式" tabindex="-1">开发模式 <a class="header-anchor" href="#开发模式" aria-label="Permalink to &quot;开发模式&quot;">​</a></h2><p>在开发过程中，Vue 前端开发服务器（默认端口 5173）与 Go 后端（默认端口 9090）分开运行。开发服务器配置了 CORS，允许跨域请求。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 1：启动 Go 后端</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端 2：启动 Vue 前端开发服务器</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internal/webui/frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>生产构建时，前端静态文件通过 <code>go:embed</code> 直接嵌入到 Go 二进制文件中，无需额外部署。</p>`,74)])])}const b=a(l,[["render",r]]);export{u as __pageData,b as default};
